@Composable
fun AddVideoDialogContent(
    viewModel: LearningViewModel,
    initialStream: String,
    onDismiss: () -> Unit,
    onSubmit: (title: String, description: String, url: String, category: String, stream: String, domain: String, thumbnailUrl: String) -> Unit
) {
    var title by remember { mutableStateOf("") }
    var description by remember { mutableStateOf("") }
    var url by remember { mutableStateOf("") }
    var category by remember { mutableStateOf("Domain") }
    var stream by remember { mutableStateOf(initialStream) }
    var domain by remember { mutableStateOf("") }
    var thumbnailUrl by remember { mutableStateOf("") }
    var statusMessage by remember { mutableStateOf<String?>(null) }

    LaunchedEffect(stream) {
        val list = com.example.data.StreamDomains[stream] ?: emptyList()
        domain = list.firstOrNull() ?: ""
    }

    Column(
        modifier = Modifier
            .padding(18.dp)
            .verticalScroll(rememberScrollState()),
        verticalArrangement = Arrangement.spacedBy(14.dp)
    ) {
        Text("Add Video Lecture", fontSize = 18.sp, fontWeight = FontWeight.Bold)

        OutlinedTextField(
            value = title,
            onValueChange = { title = it },
            label = { Text("Lecture Title") },
            modifier = Modifier.fillMaxWidth(),
            colors = getHighContrastTextFieldColors()
        )

        OutlinedTextField(
            value = description,
            onValueChange = { description = it },
            label = { Text("Description") },
            modifier = Modifier.fillMaxWidth(),
            maxLines = 3,
            colors = getHighContrastTextFieldColors()
        )

        OutlinedTextField(
            value = url,
            onValueChange = { url = it; statusMessage = null },
            label = { Text("YouTube Video Link") },
            placeholder = { Text("e.g. https://www.youtube.com/watch?v=... or https://youtu.be/...") },
            modifier = Modifier.fillMaxWidth(),
            colors = getHighContrastTextFieldColors()
        )

        OutlinedTextField(
            value = thumbnailUrl,
            onValueChange = { thumbnailUrl = it },
            label = { Text("Thumbnail Image URL (optional)") },
            placeholder = { Text("e.g. https://example.com/thumb.jpg") },
            modifier = Modifier.fillMaxWidth(),
            colors = getHighContrastTextFieldColors()
        )

        if (statusMessage != null) {
            Text(
                text = statusMessage!!,
                fontSize = 11.sp,
                fontWeight = FontWeight.Bold,
                color = Color.Red
            )
        }

        // Category Selection
        Column {
            Text("Category:", fontSize = 12.sp, fontWeight = FontWeight.Bold, color = GeoPalette.TextSecondary)
            Row(horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                listOf("General", "Domain", "TeachingAptitude").forEach { cat ->
                    Box(
                        modifier = Modifier
                            .border(1.dp, if (category == cat) GeoPalette.Primary else GeoPalette.CardBorder, RoundedCornerShape(8.dp))
                            .background(if (category == cat) GeoPalette.PrimaryContainer else Color.Transparent, RoundedCornerShape(8.dp))
                            .clickable { category = cat }
                            .padding(horizontal = 10.dp, vertical = 6.dp)
                    ) {
                        Text(cat, fontSize = 11.sp, fontWeight = FontWeight.Bold)
                    }
                }
            }
        }

        // Stream Selection
        Column {
            Text("Applicable Stream:", fontSize = 12.sp, fontWeight = FontWeight.Bold, color = GeoPalette.TextSecondary)
            Row(horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                listOf("Science", "Commerce", "Humanities").forEach { currentStream ->
                    Box(
                        modifier = Modifier
                            .border(1.dp, if (stream == currentStream) GeoPalette.Primary else GeoPalette.CardBorder, RoundedCornerShape(8.dp))
                            .background(if (stream == currentStream) GeoPalette.PrimaryContainer else Color.Transparent, RoundedCornerShape(8.dp))
                            .clickable { stream = currentStream }
                            .padding(horizontal = 10.dp, vertical = 6.dp)
                    ) {
                        Text(currentStream, fontSize = 11.sp, fontWeight = FontWeight.Bold)
                    }
                }
            }
        }

        // Domain Selector
        DomainSelector(
            selectedStream = stream,
            selectedDomain = domain,
            onDomainSelected = { domain = it }
        )

        Row(horizontalArrangement = Arrangement.spacedBy(10.dp), modifier = Modifier.fillMaxWidth()) {
            OutlinedButton(onClick = onDismiss, modifier = Modifier.weight(1f)) {
                Text("Cancel")
            }
            Button(
                onClick = {
                    if (title.isBlank()) {
                        statusMessage = "Please enter a lecture title"
                        return@Button
                    }
                    if (!isYouTubeUrl(url)) {
                        statusMessage = "Invalid YouTube URL! Please enter a valid link (e.g. https://www.youtube.com/watch?v=... or https://youtu.be/...)"
                        return@Button
                    }
                    onSubmit(title, description, url, category, stream, domain, thumbnailUrl)
                },
                colors = ButtonDefaults.buttonColors(containerColor = GeoPalette.Primary),
                modifier = Modifier
                    .weight(1f)
                    .testTag("add_content_button"),
                shape = RoundedCornerShape(10.dp)
            ) {
                Text("Add Video", fontWeight = FontWeight.Bold)
            }
        }
    }
}

